The actual application entrypoints are application.write and application.read. A write is acknowledged only when application.write returns its success dictionary, after transaction commit and connection close; exceptions are not acknowledgments. Use existing keys for updates and fresh keys for inserts. Calls are sequential; each completed acknowledged write must be visible through both versions on fresh connections before the next call. No concurrent request ordering or crash-durability claim is requested. All acknowledged values must survive the documented rollback.
import sqlite3
import versions


def write(path, version, operation, key, value):
    handler = {('old', 'update'): versions.old_write,
               ('new', 'update'): versions.new_write,
               ('old', 'insert'): versions.old_insert,
               ('new', 'insert'): versions.new_insert}[(version, operation)]
    db = sqlite3.connect(path, timeout=1)
    try:
        with db:
            handler(db, key, value)
    finally:
        db.close()
    return {'acknowledged': True, 'id': key, 'value': value}


def read(path, version, key):
    db = sqlite3.connect(path, timeout=1)
    try:
        return {'old': versions.old_read, 'new': versions.new_read}[version](db, key)
